import React, { useEffect, useRef } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { RoomEnvironment } from "three/examples/jsm/environments/RoomEnvironment.js";
import { toCreasedNormals } from "three/examples/jsm/utils/BufferGeometryUtils.js";

const modelUrl = (name) => `${process.env.PUBLIC_URL || ""}/assets/models/${name}.bin`;

// Binary layout written by scripts/export_models.py: uint32 header length, a JSON header
// listing the parts, then per part float32 positions and uint16 indices (4-byte aligned).
// Every part of a file shares one frame (centred, longest side = 2).
const parseScene = (buffer) => {
  const headerLength = new DataView(buffer, 0, 4).getUint32(0, true);
  const { parts } = JSON.parse(new TextDecoder().decode(new Uint8Array(buffer, 4, headerLength)));
  let offset = 4 + headerLength;
  return parts.map(({ kind, vertices, indices }) => {
    const positions = new Float32Array(buffer, offset, vertices * 3);
    offset += vertices * 12;
    const index = new Uint16Array(buffer, offset, indices);
    offset += Math.ceil((indices * 2) / 4) * 4;
    return { kind, positions, index };
  });
};

// How each kind of part is painted. "result" is the finished metal part; the others are the
// client's inputs: a faint grey envelope, red keep-out blocks and blue slots/cylinders.
const SURFACES = {
  result: { color: 0xd5dde9, metalness: 0.55, roughness: 0.42, envMapIntensity: 1.5, edge: 0.28 },
  bounds: { color: 0x8e8e93, metalness: 0, roughness: 0.9, opacity: 0.1, edge: 0.35 },
  block: { color: 0xe5342b, metalness: 0.05, roughness: 0.6, opacity: 0.4, edge: 0.55 },
  feature: { color: 0x0a6cf5, metalness: 0.2, roughness: 0.45, envMapIntensity: 1.2, opacity: 0.6, edge: 0.4 },
};

const IDLE_RESUME_MS = 2500;

// Viewers that share a `syncGroup` turn together: whichever one the visitor last grabbed (or,
// before any interaction, the first to load) drives, and the others copy its azimuth and
// elevation every frame. Each keeps its own orbit limits, distance and auto-rotation speed, so
// the motion is exactly what a lone viewer does, just in step.
const syncGroups = new Map();
const getSyncGroup = (name) => {
  if (!syncGroups.has(name)) syncGroups.set(name, { driver: null, azimuth: null, polar: null, subs: new Set() });
  return syncGroups.get(name);
};
// The part always stays inside this fraction of the stage, from every viewing angle.
const FIT_MARGIN = 0.96;

const PartViewer = ({ model = "result", syncGroup, onReady, onFail }) => {
  const mountRef = useRef(null);

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return undefined;

    const reducedMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

    let renderer;
    try {
      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: "low-power" });
    } catch (e) {
      onFail?.(e);
      return undefined;
    }
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 0.9;
    renderer.setClearColor(0x000000, 0);
    renderer.domElement.style.cssText = "display:block;width:100%;height:100%;touch-action:pan-y;";
    mount.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const pmrem = new THREE.PMREMGenerator(renderer);
    const envTexture = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
    scene.environment = envTexture;

    scene.add(new THREE.HemisphereLight(0xffffff, 0xaebbd0, 0.9));
    const key = new THREE.DirectionalLight(0xffffff, 1.4);
    key.position.set(3, 4, 2.5);
    scene.add(key);

    const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 50);
    camera.position.set(2.1, 1.15, 2.4);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableZoom = false;
    controls.enablePan = false;
    controls.enableDamping = true;
    controls.dampingFactor = 0.07;
    controls.autoRotate = !reducedMotion;
    controls.autoRotateSpeed = 1.1;
    controls.minPolarAngle = Math.PI * 0.18;
    controls.maxPolarAngle = Math.PI * 0.62;
    // OrbitControls claims every touch; give vertical swipes back to the page scroll.
    renderer.domElement.style.touchAction = "pan-y";

    const sync = syncGroup ? getSyncGroup(syncGroup) : null;
    const id = Symbol(model);
    const isFollower = () => sync !== null && sync.driver !== null && sync.driver !== id && sync.azimuth !== null;

    let wantsAutoRotate = !reducedMotion;
    let resumeTimer = null;
    controls.addEventListener("start", () => {
      wantsAutoRotate = false;
      if (sync) sync.driver = id;
      clearTimeout(resumeTimer);
    });
    controls.addEventListener("end", () => {
      if (reducedMotion) return;
      clearTimeout(resumeTimer);
      resumeTimer = setTimeout(() => {
        wantsAutoRotate = true;
      }, IDLE_RESUME_MS);
    });

    let disposed = false;
    let visible = true;
    let rafId = null;
    const disposables = [];
    let fitCorners = null; // the part's bounding-box corners, in world space

    const render = () => {
      if (isFollower()) {
        controls.autoRotate = false;
        camera.position.setFromSphericalCoords(camera.position.length(), sync.polar, sync.azimuth);
      } else {
        controls.autoRotate = wantsAutoRotate;
      }
      controls.update();
      if (sync && sync.driver === id) {
        const { x, y, z } = camera.position;
        sync.azimuth = Math.atan2(x, z);
        sync.polar = Math.acos(Math.min(1, Math.max(-1, y / camera.position.length())));
        if (reducedMotion) sync.subs.forEach((notify) => notify !== render && notify());
      }
      renderer.render(scene, camera);
    };
    if (sync && reducedMotion) sync.subs.add(render);

    const loop = () => {
      rafId = null;
      if (disposed || !visible || document.hidden) return;
      render();
      rafId = requestAnimationFrame(loop);
    };
    const start = () => {
      if (rafId === null && !disposed) rafId = requestAnimationFrame(loop);
    };

    // Camera distance that keeps the whole part on screen from every angle the visitor can
    // reach (auto-rotation sweeps all azimuths; dragging changes the elevation within the
    // polar limits). Measured on the real bounding box rather than guessed, so it holds for
    // any stage shape: wide desktop, square, or a phone.
    const probe = new THREE.PerspectiveCamera(camera.fov, 1, 0.1, 50);
    const point = new THREE.Vector3();
    const worstExtent = (distance) => {
      probe.aspect = camera.aspect;
      probe.updateProjectionMatrix();
      const polars = [controls.minPolarAngle, (controls.minPolarAngle + controls.maxPolarAngle) / 2, controls.maxPolarAngle];
      let worst = 0;
      for (const polar of polars) {
        for (let step = 0; step < 24; step++) {
          const azimuth = (step / 24) * Math.PI * 2;
          probe.position.set(
            distance * Math.sin(polar) * Math.sin(azimuth),
            distance * Math.cos(polar),
            distance * Math.sin(polar) * Math.cos(azimuth)
          );
          probe.lookAt(0, 0, 0);
          probe.updateMatrixWorld();
          probe.matrixWorldInverse.copy(probe.matrixWorld).invert();
          for (const corner of fitCorners) {
            point.copy(corner).project(probe);
            worst = Math.max(worst, Math.abs(point.x), Math.abs(point.y));
          }
        }
      }
      return worst;
    };
    const fitDistance = () => {
      let near = 2;
      let far = 16;
      for (let i = 0; i < 14; i++) {
        const mid = (near + far) / 2;
        if (worstExtent(mid) > FIT_MARGIN) near = mid;
        else far = mid;
      }
      return far;
    };

    const resize = () => {
      const { clientWidth: w, clientHeight: h } = mount;
      if (!w || !h) return;
      renderer.setSize(w, h, false);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      if (fitCorners) {
        camera.position.setLength(fitDistance());
        controls.update();
      }
      if (reducedMotion || !visible) render();
    };
    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(mount);
    resize();

    const visibilityObserver = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      if (visible) start();
    });
    visibilityObserver.observe(mount);
    const onVisibilityChange = () => {
      if (!document.hidden) start();
    };
    document.addEventListener("visibilitychange", onVisibilityChange);

    if (reducedMotion) controls.addEventListener("change", render);

    fetch(modelUrl(model))
      .then((res) => {
        if (!res.ok) throw new Error(`Model request failed: ${res.status}`);
        return res.arrayBuffer();
      })
      .then((buffer) => {
        if (disposed) return;
        const group = new THREE.Group();
        const bounds = new THREE.Box3();
        parseScene(buffer).forEach(({ kind, positions, index }) => {
          const surface = SURFACES[kind] || SURFACES.result;
          const base = new THREE.BufferGeometry();
          base.setAttribute("position", new THREE.BufferAttribute(positions, 3));
          base.setIndex(new THREE.BufferAttribute(index, 1));
          // Crease angle keeps machined edges crisp while fillets and bores stay smooth.
          const geometry = toCreasedNormals(base, THREE.MathUtils.degToRad(32));
          base.dispose();

          const translucent = surface.opacity !== undefined;
          const material = new THREE.MeshStandardMaterial({
            color: surface.color,
            metalness: surface.metalness,
            roughness: surface.roughness,
            envMapIntensity: surface.envMapIntensity ?? 1,
            transparent: translucent,
            opacity: translucent ? surface.opacity : 1,
            depthWrite: !translucent,
          });
          const mesh = new THREE.Mesh(geometry, material);
          // Translucent shells draw after the solid parts so those show through them.
          if (translucent) mesh.renderOrder = kind === "bounds" ? 2 : kind === "block" ? 1 : 0;

          const edgeMaterial = new THREE.LineBasicMaterial({
            color: kind === "result" ? 0x0a1a3a : kind === "bounds" ? 0x6e6e73 : 0x1d1d1f,
            transparent: true,
            opacity: surface.edge,
            depthWrite: false,
          });
          const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geometry, 38), edgeMaterial);
          edges.renderOrder = mesh.renderOrder + 1;

          group.add(mesh, edges);
          disposables.push(geometry, material, edges.geometry, edgeMaterial);

          geometry.computeBoundingBox();
          bounds.union(geometry.boundingBox);
        });
        group.rotation.set(0, -0.5, 0);
        scene.add(group);

        group.updateMatrixWorld(true);
        const { min, max } = bounds;
        fitCorners = [min.x, max.x].flatMap((x) =>
          [min.y, max.y].flatMap((y) => [min.z, max.z].map((z) => new THREE.Vector3(x, y, z).applyMatrix4(group.matrixWorld)))
        );

        controls.target.set(0, 0, 0);
        if (sync && sync.driver === null) sync.driver = id;
        resize();
        render();
        onReady?.();
        start();
      })
      .catch((e) => {
        if (sync && sync.driver === id) sync.driver = null;
        if (!disposed) onFail?.(e);
      });

    return () => {
      disposed = true;
      if (sync) {
        sync.subs.delete(render);
        if (sync.driver === id) sync.driver = null;
      }
      clearTimeout(resumeTimer);
      if (rafId) cancelAnimationFrame(rafId);
      document.removeEventListener("visibilitychange", onVisibilityChange);
      visibilityObserver.disconnect();
      resizeObserver.disconnect();
      controls.dispose();
      disposables.forEach((item) => item.dispose());
      envTexture.dispose();
      pmrem.dispose();
      renderer.dispose();
      renderer.domElement.remove();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [model]);

  return <div ref={mountRef} className="part-viewer" aria-hidden="true" />;
};

export default PartViewer;
